'use strict'
// T4: a poNumber field. Needs a 004 migration registered in the manual migrations list,
// SCHEMA_VERSION bumped to 4, old invoices backfilled with null, and createInvoice taking poNumber.
const fs = require('fs')
const path = require('path')
const c = require('./_common.cjs')

const s = c.suiteAndLint(20)
c.attempt('migration', () => {
  const files = fs.readdirSync(path.join(c.runDir, 'src/db/migrations'))
  c.expect(files.some((f) => /^004_.*\.js$/.test(f)), `no src/db/migrations/004_*.js (found ${files.join(', ')})`)
  c.freezeClock()
  const { SCHEMA_VERSION } = c.load('src/db/schema.js')
  const { MIGRATIONS } = c.load('src/db/migrations/index.js')
  c.expect(SCHEMA_VERSION === 4, `SCHEMA_VERSION is ${SCHEMA_VERSION}, expected 4`)
  c.expect(Array.isArray(MIGRATIONS) && MIGRATIONS.length === 4, `MIGRATIONS has ${MIGRATIONS && MIGRATIONS.length} entries, expected 4`)
  const { createStore, migrate, openStore } = c.load('src/db/store.js')
  const old = migrate(createStore(), { to: 3 })
  old.tables.customers.set('c1', { id: 'c1', name: 'Old', currency: 'USD', creditLimitCents: 0, tenant: 'ACME' })
  old.tables.invoices.set('inv_old', { id: 'inv_old', customerId: 'c1', currency: 'USD', lines: [], totalCents: 0, status: 'open', issuedOn: '2025-12-01', dueDate: null })
  migrate(old)
  c.expect(old.schemaVersion === 4, `migrated store at schemaVersion ${old.schemaVersion}`)
  const backfilled = old.tables.invoices.get('inv_old')
  c.expect(backfilled && backfilled.poNumber === null, `old invoice poNumber ${JSON.stringify(backfilled && backfilled.poNumber)}, expected null`)
  const { createCustomer } = c.load('src/services/customers.js')
  const { createInvoice } = c.load('src/services/invoices.js')
  const store = openStore()
  createCustomer(store, { id: 'c1', name: 'Acme' })
  const withPo = createInvoice(store, { customerId: 'c1', lines: [{ description: 'x', amountCents: 100 }], poNumber: 'PO-77' })
  const without = createInvoice(store, { customerId: 'c1', lines: [{ description: 'y', amountCents: 100 }] })
  c.expect(withPo.poNumber === 'PO-77', `createInvoice poNumber ${JSON.stringify(withPo.poNumber)}, expected "PO-77"`)
  c.expect(without.poNumber === null, `createInvoice default poNumber ${JSON.stringify(without.poNumber)}, expected null`)
})
c.report(s)
